with cleaned as (select *, status_bits - pressure as status_bits_minus_pressure from device_readings where reading_ts >= timestamp '2025-09-01 07:00:00' and hour(reading_ts) between 8 and 16), with_gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 30 minutes then 1 else 0 end as is_new_burst from cleaned), islands as (select *, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from with_gaps) select case when pressure >= 1029 then 'LARGE' else 'SMALL' end as pressure_tier, session_id, device_code, count(*) filter (where device_code = 'DV-04') as dv_04_rows, count_if(device_code = 'DV-02') as dv_02_events, corr(humidity, temp_c) as corr_humidity_temp_c, grouping(case when pressure >= 1029 then 'LARGE' else 'SMALL' end) as grouping_id from islands group by rollup (case when pressure >= 1029 then 'LARGE' else 'SMALL' end, session_id, device_code) order by corr_humidity_temp_c;
